insert into public.questions(lesson_id,prompt,options,correct,explanation,position,is_active) values ('c11-reading-check','Która teza najlepiej opisuje akapit 1?','["Redaktorka przygotowała trzy wersje tej samej wiadomości: do przyjaciela, zespołu i urzędu.","Wersja potoczna była krótka i bezpośrednia, lecz w urzędzie brzmiałaby niestosownie.","Tekst oficjalny zawierał zwrot grzecznościowy i precyzyjny cel, ale nie był chłodny."]',0,'Первый вариант точно передаёт содержание абзаца.',1,true);
insert into public.questions(lesson_id,prompt,options,correct,explanation,position,is_active) values ('c12-grammar','Wybierz wyrażenie pasujące do celu: предпосылка.','["przesłanka","tok rozumowania","kontrargument"]',0,'przesłanka oznacza: предпосылка.',1,true);
insert into public.questions(lesson_id,prompt,options,correct,explanation,position,is_active) values ('c12-quiz','Co znaczy „przesłanka”?','["предпосылка","ход рассуждения","контраргумент"]',0,'„przesłanka” — предпосылка.',1,true);
insert into public.questions(lesson_id,prompt,options,correct,explanation,position,is_active) values ('c12-reading-check','Która teza najlepiej opisuje akapit 1?','["Rada debatowała nad ograniczeniem ruchu w centrum i analizowała kilka sprzecznych danych.","Zwolennicy wskazali poprawę jakości powietrza, przyznając zarazem, że dostawy mogą być trudniejsze.","Przeciwnicy przedstawili kontrargument dotyczący kosztów, lecz pojedynczy przykład nie przesądzał wyniku."]',0,'Первый вариант точно передаёт содержание абзаца.',1,true);
insert into public.questions(lesson_id,prompt,options,correct,explanation,position,is_active) values ('c13-grammar','Wybierz wyrażenie pasujące do celu: интерпретационная рамка.','["rama interpretacyjna","dobór przykładów","pominięcie"]',0,'rama interpretacyjna oznacza: интерпретационная рамка.',1,true);
insert into public.questions(lesson_id,prompt,options,correct,explanation,position,is_active) values ('c13-quiz','Co znaczy „rama interpretacyjna”?','["интерпретационная рамка","подбор примеров","умолчание"]',0,'„rama interpretacyjna” — интерпретационная рамка.',1,true);
insert into public.questions(lesson_id,prompt,options,correct,explanation,position,is_active) values ('c13-reading-check','Która teza najlepiej opisuje akapit 1?','["Studentka porównała dwa komentarze o tej samej zmianie w mieście.","Pierwszy tekst pozornie neutralnie wyliczał koszty, lecz pomijał korzyści i głosy mieszkańców.","Drugi używał ironicznych pytań, dlatego jego wydźwięk był wyraźnie wartościujący."]',0,'Первый вариант точно передаёт содержание абзаца.',1,true);
insert into public.questions(lesson_id,prompt,options,correct,explanation,position,is_active) values ('c14-grammar','Wybierz wyrażenie pasujące do celu: неспециалист.','["odbiorca niespecjalistyczny","przełożyć na prosty język","uniknąć uproszczenia"]',0,'odbiorca niespecjalistyczny oznacza: неспециалист.',1,true);
insert into public.questions(lesson_id,prompt,options,correct,explanation,position,is_active) values ('c14-quiz','Co znaczy „odbiorca niespecjalistyczny”?','["неспециалист","переложить простым языком","избежать упрощения"]',0,'„odbiorca niespecjalistyczny” — неспециалист.',1,true);
insert into public.questions(lesson_id,prompt,options,correct,explanation,position,is_active) values ('c14-reading-check','Która teza najlepiej opisuje akapit 1?','["Analityczka miała wyjaśnić mieszkańcom raport o retencji wody, pełen terminów technicznych.","Najpierw wydobyła sedno: więcej zieleni spowalnia odpływ i zmniejsza ryzyko lokalnych podtopień.","Podała analogię do gąbki, ale zaznaczyła, że park nie zatrzyma każdej ulewy."]',0,'Первый вариант точно передаёт содержание абзаца.',1,true);
insert into public.questions(lesson_id,prompt,options,correct,explanation,position,is_active) values ('c11-grammar','Wybierz wyrażenie pasujące do celu: формула вежливости.','["zwrot grzecznościowy","potoczny","neutralny"]',0,'zwrot grzecznościowy oznacza: формула вежливости.',2,true);
insert into public.questions(lesson_id,prompt,options,correct,explanation,position,is_active) values ('c11-quiz','Co znaczy „zwrot grzecznościowy”?','["формула вежливости","разговорный","нейтральный"]',0,'„zwrot grzecznościowy” — формула вежливости.',2,true);
insert into public.questions(lesson_id,prompt,options,correct,explanation,position,is_active) values ('c11-reading-check','Która teza najlepiej opisuje akapit 2?','["Wersja potoczna była krótka i bezpośrednia, lecz w urzędzie brzmiałaby niestosownie.","Tekst oficjalny zawierał zwrot grzecznościowy i precyzyjny cel, ale nie był chłodny.","Redaktorka zauważyła, że nadmierna uprzejmość może brzmieć protekcjonalnie."]',0,'Первый вариант точно передаёт содержание абзаца.',2,true);
insert into public.questions(lesson_id,prompt,options,correct,explanation,position,is_active) values ('c12-grammar','Wybierz wyrażenie pasujące do celu: ход рассуждения.','["tok rozumowania","kontrargument","obalić zarzut"]',0,'tok rozumowania oznacza: ход рассуждения.',2,true);
insert into public.questions(lesson_id,prompt,options,correct,explanation,position,is_active) values ('c12-quiz','Co znaczy „tok rozumowania”?','["ход рассуждения","контраргумент","опровергнуть возражение"]',0,'„tok rozumowania” — ход рассуждения.',2,true);
insert into public.questions(lesson_id,prompt,options,correct,explanation,position,is_active) values ('c12-reading-check','Która teza najlepiej opisuje akapit 2?','["Zwolennicy wskazali poprawę jakości powietrza, przyznając zarazem, że dostawy mogą być trudniejsze.","Przeciwnicy przedstawili kontrargument dotyczący kosztów, lecz pojedynczy przykład nie przesądzał wyniku.","Ekspert zważył argumenty i oddzielił przesłanki od założeń, których raport nie potwierdzał."]',0,'Первый вариант точно передаёт содержание абзаца.',2,true);
insert into public.questions(lesson_id,prompt,options,correct,explanation,position,is_active) values ('c13-grammar','Wybierz wyrażenie pasujące do celu: подбор примеров.','["dobór przykładów","pominięcie","wydźwięk"]',0,'dobór przykładów oznacza: подбор примеров.',2,true);
