insert into public.questions(lesson_id,prompt,options,correct,explanation,position,is_active) values ('c13-reading-check','Która teza najlepiej opisuje akapit 2?','["Pierwszy tekst pozornie neutralnie wyliczał koszty, lecz pomijał korzyści i głosy mieszkańców.","Drugi używał ironicznych pytań, dlatego jego wydźwięk był wyraźnie wartościujący.","Studentka zbadała dobór przykładów, źródła i ramę interpretacyjną zamiast zgadywać poglądy autora."]',0,'Первый вариант точно передаёт содержание абзаца.',2,true);
