insert into public.reading_texts(id,topic_id,title,description,level,minutes,emoji,paragraphs,glossary,source_metadata,position,is_active) values ('c11-tekst','c1-style-register','Стиль и регистр','Адаптируем речь к аудитории и ситуации','C1',14,'🎭','["Redaktorka przygotowała trzy wersje tej samej wiadomości: do przyjaciela, zespołu i urzędu.","Wersja potoczna była krótka i bezpośrednia, lecz w urzędzie brzmiałaby niestosownie.","Tekst oficjalny zawierał zwrot grzecznościowy i precyzyjny cel, ale nie był chłodny.","Redaktorka zauważyła, że nadmierna uprzejmość może brzmieć protekcjonalnie.","Dobry rejestr nie polega na trudnych słowach, tylko na świadomym dopasowaniu tonu do adresata."]','{"rejestr":{"lemma":"rejestr","translation":"регистр","part_of_speech":"wyrażenie"},"dobór słów":{"lemma":"dobór słów","translation":"выбор слов","part_of_speech":"wyrażenie"},"zwrot grzecznościowy":{"lemma":"zwrot grzecznościowy","translation":"формула вежливости","part_of_speech":"wyrażenie"},"potoczny":{"lemma":"potoczny","translation":"разговорный","part_of_speech":"wyrażenie"},"neutralny":{"lemma":"neutralny","translation":"нейтральный","part_of_speech":"wyrażenie"},"oficjalny":{"lemma":"oficjalny","translation":"официальный","part_of_speech":"wyrażenie"},"dostosować wypowiedź":{"lemma":"dostosować wypowiedź","translation":"адаптировать высказывание","part_of_speech":"wyrażenie"},"zachować dystans":{"lemma":"zachować dystans","translation":"сохранять дистанцию","part_of_speech":"wyrażenie"},"skrócić dystans":{"lemma":"skrócić dystans","translation":"сократить дистанцию","part_of_speech":"wyrażenie"},"brzmieć protekcjonalnie":{"lemma":"brzmieć protekcjonalnie","translation":"звучать покровительственно","part_of_speech":"wyrażenie"},"niestosowny":{"lemma":"niestosowny","translation":"неуместный","part_of_speech":"wyrażenie"},"adresat":{"lemma":"adresat","translation":"адресат","part_of_speech":"wyrażenie"},"kontekst sytuacyjny":{"lemma":"kontekst sytuacyjny","translation":"ситуативный контекст","part_of_speech":"wyrażenie"},"przeredagować":{"lemma":"przeredagować","translation":"переформулировать","part_of_speech":"wyrażenie"},"wyważyć ton":{"lemma":"wyważyć ton","translation":"выверить тон","part_of_speech":"wyrażenie"}}','{"origin":"original","created_for":"PolskiFlow","verified_at":"2026-08-30","comprehension_lesson_id":"c11-reading-check"}',47,true) on conflict(id) do update set topic_id=excluded.topic_id,title=excluded.title,description=excluded.description,level=excluded.level,minutes=excluded.minutes,emoji=excluded.emoji,paragraphs=excluded.paragraphs,glossary=excluded.glossary,source_metadata=excluded.source_metadata,position=excluded.position,is_active=excluded.is_active;
insert into public.reading_texts(id,topic_id,title,description,level,minutes,emoji,paragraphs,glossary,source_metadata,position,is_active) values ('c12-tekst','c1-complex-argument','Сложная аргументация','Строим позицию с оговорками и контраргументом','C1',14,'⚖️','["Rada debatowała nad ograniczeniem ruchu w centrum i analizowała kilka sprzecznych danych.","Zwolennicy wskazali poprawę jakości powietrza, przyznając zarazem, że dostawy mogą być trudniejsze.","Przeciwnicy przedstawili kontrargument dotyczący kosztów, lecz pojedynczy przykład nie przesądzał wyniku.","Ekspert zważył argumenty i oddzielił przesłanki od założeń, których raport nie potwierdzał.","Wniosek poparł pilotaż o tyle, o ile miasto równolegle zbada dostępność i skutki dla handlu."]','{"zastrzeżenie":{"lemma":"zastrzeżenie","translation":"оговорка","part_of_speech":"wyrażenie"},"przesłanka":{"lemma":"przesłanka","translation":"предпосылка","part_of_speech":"wyrażenie"},"tok rozumowania":{"lemma":"tok rozumowania","translation":"ход рассуждения","part_of_speech":"wyrażenie"},"kontrargument":{"lemma":"kontrargument","translation":"контраргумент","part_of_speech":"wyrażenie"},"obalić zarzut":{"lemma":"obalić zarzut","translation":"опровергнуть возражение","part_of_speech":"wyrażenie"},"przyznać rację":{"lemma":"przyznać rację","translation":"признать правоту","part_of_speech":"wyrażenie"},"z dużym prawdopodobieństwem":{"lemma":"z dużym prawdopodobieństwem","translation":"с большой вероятностью","part_of_speech":"wyrażenie"},"nie przesądza":{"lemma":"nie przesądza","translation":"не предрешает","part_of_speech":"wyrażenie"},"o tyle, o ile":{"lemma":"o tyle, o ile","translation":"постольку, поскольку","part_of_speech":"wyrażenie"},"tym niemniej":{"lemma":"tym niemniej","translation":"тем не менее","part_of_speech":"wyrażenie"},"wynikać pośrednio":{"lemma":"wynikać pośrednio","translation":"косвенно следовать","part_of_speech":"wyrażenie"},"uprawniony wniosek":{"lemma":"uprawniony wniosek","translation":"обоснованный вывод","part_of_speech":"wyrażenie"},"nadużycie":{"lemma":"nadużycie","translation":"злоупотребление","part_of_speech":"wyrażenie"},"ważyć argumenty":{"lemma":"ważyć argumenty","translation":"взвешивать аргументы","part_of_speech":"wyrażenie"},"niuansować stanowisko":{"lemma":"niuansować stanowisko","translation":"нюансировать позицию","part_of_speech":"wyrażenie"}}','{"origin":"original","created_for":"PolskiFlow","verified_at":"2026-08-30","comprehension_lesson_id":"c12-reading-check"}',48,true) on conflict(id) do update set topic_id=excluded.topic_id,title=excluded.title,description=excluded.description,level=excluded.level,minutes=excluded.minutes,emoji=excluded.emoji,paragraphs=excluded.paragraphs,glossary=excluded.glossary,source_metadata=excluded.source_metadata,position=excluded.position,is_active=excluded.is_active;
insert into public.reading_texts(id,topic_id,title,description,level,minutes,emoji,paragraphs,glossary,source_metadata,position,is_active) values ('c13-tekst','c1-analytical-reading','Аналитическое чтение','Выявляем предпосылки, тон и стратегию автора','C1',14,'🔎','["Studentka porównała dwa komentarze o tej samej zmianie w mieście.","Pierwszy tekst pozornie neutralnie wyliczał koszty, lecz pomijał korzyści i głosy mieszkańców.","Drugi używał ironicznych pytań, dlatego jego wydźwięk był wyraźnie wartościujący.","Studentka zbadała dobór przykładów, źródła i ramę interpretacyjną zamiast zgadywać poglądy autora.","Uznała, że analityczne czytanie oddziela treść jawną od wniosku sugerowanego przez strukturę tekstu."]','{"założenie ukryte":{"lemma":"założenie ukryte","translation":"скрытая предпосылка","part_of_speech":"wyrażenie"},"rama interpretacyjna":{"lemma":"rama interpretacyjna","translation":"интерпретационная рамка","part_of_speech":"wyrażenie"},"dobór przykładów":{"lemma":"dobór przykładów","translation":"подбор примеров","part_of_speech":"wyrażenie"},"pominięcie":{"lemma":"pominięcie","translation":"умолчание","part_of_speech":"wyrażenie"},"wydźwięk":{"lemma":"wydźwięk","translation":"оттенок, звучание","part_of_speech":"wyrażenie"},"ironiczny":{"lemma":"ironiczny","translation":"ироничный","part_of_speech":"wyrażenie"},"wartościujący":{"lemma":"wartościujący","translation":"оценочный","part_of_speech":"wyrażenie"},"pozornie neutralny":{"lemma":"pozornie neutralny","translation":"внешне нейтральный","part_of_speech":"wyrażenie"},"sugerować":{"lemma":"sugerować","translation":"намекать","part_of_speech":"wyrażenie"},"podważać":{"lemma":"podważać","translation":"ставить под сомнение","part_of_speech":"wyrażenie"},"strategia autora":{"lemma":"strategia autora","translation":"стратегия автора","part_of_speech":"wyrażenie"},"wiarygodność":{"lemma":"wiarygodność","translation":"достоверность","part_of_speech":"wyrażenie"},"punkt widzenia":{"lemma":"punkt widzenia","translation":"точка зрения","part_of_speech":"wyrażenie"},"odczytać intencję":{"lemma":"odczytać intencję","translation":"считать намерение","part_of_speech":"wyrażenie"},"wniosek implicytny":{"lemma":"wniosek implicytny","translation":"имплицитный вывод","part_of_speech":"wyrażenie"}}','{"origin":"original","created_for":"PolskiFlow","verified_at":"2026-08-30","comprehension_lesson_id":"c13-reading-check"}',49,true) on conflict(id) do update set topic_id=excluded.topic_id,title=excluded.title,description=excluded.description,level=excluded.level,minutes=excluded.minutes,emoji=excluded.emoji,paragraphs=excluded.paragraphs,glossary=excluded.glossary,source_metadata=excluded.source_metadata,position=excluded.position,is_active=excluded.is_active;
insert into public.reading_texts(id,topic_id,title,description,level,minutes,emoji,paragraphs,glossary,source_metadata,position,is_active) values ('c14-tekst','c1-mediation','Медиация','Передаём сложную информацию неспециалисту','C1',14,'🧩','["Analityczka miała wyjaśnić mieszkańcom raport o retencji wody, pełen terminów technicznych.","Najpierw wydobyła sedno: więcej zieleni spowalnia odpływ i zmniejsza ryzyko lokalnych podtopień.","Podała analogię do gąbki, ale zaznaczyła, że park nie zatrzyma każdej ulewy.","Pominęła wzory, zachowała natomiast liczby potrzebne do porównania wariantów i objaśniła ich zależność.","Na końcu poprosiła odbiorców o własne podsumowanie, aby sprawdzić zrozumienie bez infantylizowania rozmowy."]','{"sedno":{"lemma":"sedno","translation":"суть","part_of_speech":"wyrażenie"},"odbiorca niespecjalistyczny":{"lemma":"odbiorca niespecjalistyczny","translation":"неспециалист","part_of_speech":"wyrażenie"},"przełożyć na prosty język":{"lemma":"przełożyć na prosty język","translation":"переложить простым языком","part_of_speech":"wyrażenie"},"uniknąć uproszczenia":{"lemma":"uniknąć uproszczenia","translation":"избежать упрощения","part_of_speech":"wyrażenie"},"objaśnić pojęcie":{"lemma":"objaśnić pojęcie","translation":"объяснить понятие","part_of_speech":"wyrażenie"},"zachować zastrzeżenie":{"lemma":"zachować zastrzeżenie","translation":"сохранить оговорку","part_of_speech":"wyrażenie"},"uporządkować informacje":{"lemma":"uporządkować informacje","translation":"структурировать информацию","part_of_speech":"wyrażenie"},"podać analogię":{"lemma":"podać analogię","translation":"привести аналогию","part_of_speech":"wyrażenie"},"wyjaśnić zależność":{"lemma":"wyjaśnić zależność","translation":"объяснить зависимость","part_of_speech":"wyrażenie"},"pominąć detal":{"lemma":"pominąć detal","translation":"опустить деталь","part_of_speech":"wyrażenie"},"sprawdzić zrozumienie":{"lemma":"sprawdzić zrozumienie","translation":"проверить понимание","part_of_speech":"wyrażenie"},"podsumować":{"lemma":"podsumować","translation":"подвести итог","part_of_speech":"wyrażenie"},"pośredniczyć":{"lemma":"pośredniczyć","translation":"посредничать","part_of_speech":"wyrażenie"},"wiernie oddać sens":{"lemma":"wiernie oddać sens","translation":"точно передать смысл","part_of_speech":"wyrażenie"},"stopniować trudność":{"lemma":"stopniować trudność","translation":"дозировать сложность","part_of_speech":"wyrażenie"}}','{"origin":"original","created_for":"PolskiFlow","verified_at":"2026-08-30","comprehension_lesson_id":"c14-reading-check"}',50,true) on conflict(id) do update set topic_id=excluded.topic_id,title=excluded.title,description=excluded.description,level=excluded.level,minutes=excluded.minutes,emoji=excluded.emoji,paragraphs=excluded.paragraphs,glossary=excluded.glossary,source_metadata=excluded.source_metadata,position=excluded.position,is_active=excluded.is_active;
